function toBase(n, base) {
  if (typeof n !== "bigint") throw new TypeError("Use a BigInt value");
  if (n < 0n || !Number.isInteger(base) || base < 2 || base > 36)
    throw new RangeError("Use n >= 0 and an integer base from 2 through 36");
  if (n === 0n) return "0";
  const alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  const b = BigInt(base), digits = [];
  while (n > 0n) {
    digits.push(alphabet[Number(n % b)]);
    n /= b;
  }
  return digits.reverse().join("");
}

function fromBase(text, base) {
  if (typeof text !== "string" || text.length === 0)
    throw new TypeError("Use a nonempty digit string");
  if (!Number.isInteger(base) || base < 2 || base > 36)
    throw new RangeError("Use an integer base from 2 through 36");
  const alphabet = "0123456789ABCDEFGHIJKLMNOPQRSTUVWXYZ";
  const b = BigInt(base);
  let n = 0n;
  for (const ch of text) {
    const digit = alphabet.indexOf(ch);
    if (digit < 0 || digit >= base)
      throw new RangeError("A digit is invalid for this base");
    n = n * b + BigInt(digit);
  }
  return n;
}

function addBinary(a, b) {
  if (typeof a !== "string" || typeof b !== "string" ||
      !/^[01]+$/.test(a) || !/^[01]+$/.test(b))
    throw new TypeError("Use nonempty binary strings");
  let i = a.length - 1, j = b.length - 1, carry = 0;
  const digits = [];
  while (i >= 0 || j >= 0 || carry !== 0) {
    const x = i >= 0 ? Number(a[i--]) : 0;
    const y = j >= 0 ? Number(b[j--]) : 0;
    const total = x + y + carry;
    digits.push(String(total % 2));
    carry = Math.floor(total / 2);
  }
  return digits.reverse().join("").replace(/^0+(?=.)/, "");
}

function repeatedDivision(a, d) {
  if (typeof a !== "bigint" || typeof d !== "bigint")
    throw new TypeError("Use BigInt integers");
  if (d <= 0n) throw new RangeError("The divisor must be positive");
  let q = 0n, r = a < 0n ? -a : a;
  while (r >= d) { r -= d; q += 1n; }
  if (a < 0n) {
    if (r === 0n) q = -q;
    else { q = -q - 1n; r = d - r; }
  }
  return { q, r };
}

function binaryDivision(n, d) {
  if (typeof n !== "bigint" || typeof d !== "bigint")
    throw new TypeError("Use BigInt integers");
  if (n < 0n || d <= 0n)
    throw new RangeError("Use n >= 0 and d > 0");
  let q = 0n, r = 0n;
  for (const ch of n.toString(2)) {
    q *= 2n;
    r = 2n * r + BigInt(ch);
    if (r >= d) { r -= d; q += 1n; }
  }
  return { q, r };
}

function modPower(b, n, m) {
  if (typeof b !== "bigint" || typeof n !== "bigint" ||
      typeof m !== "bigint") throw new TypeError("Use BigInt integers");
  if (n < 0n || m <= 0n)
    throw new RangeError("Use an exponent >= 0 and a modulus > 0");
  let result = 1n % m;
  let power = ((b % m) + m) % m;
  let remaining = n;
  while (remaining > 0n) {
    if (remaining % 2n === 1n) result = (result * power) % m;
    power = (power * power) % m;
    remaining /= 2n;
  }
  return result;
}
